-- SQL Schema generated by MODT

CREATE TABLE Person (
    id INT PRIMARY KEY AUTO_INCREMENT,
    nationalId VARCHAR(20),
    fullName VARCHAR(140) NOT NULL,
    birthDate date,
    phone VARCHAR(30)
);

CREATE TABLE Patient (
    id INT PRIMARY KEY AUTO_INCREMENT,
    parent INT,
    medicalRecordNumber VARCHAR(40) UNIQUE NOT NULL,
    riskLevel VARCHAR(20),
    consentSigned BOOLEAN DEFAULT FALSE,
    FOREIGN KEY (parent) REFERENCES Person(id)
);

CREATE TABLE StaffMember (
    id INT PRIMARY KEY AUTO_INCREMENT,
    parent INT,
    employeeCode VARCHAR(30) UNIQUE NOT NULL,
    hireDate date,
    FOREIGN KEY (parent) REFERENCES Person(id)
);

CREATE TABLE Physician (
    id INT PRIMARY KEY AUTO_INCREMENT,
    parent INT,
    specialty VARCHAR(80) NOT NULL,
    FOREIGN KEY (parent) REFERENCES StaffMember(id)
);

CREATE TABLE Nurse (
    id INT PRIMARY KEY AUTO_INCREMENT,
    parent INT,
    shiftName VARCHAR(30),
    FOREIGN KEY (parent) REFERENCES StaffMember(id)
);

CREATE TABLE Appointment (
    id INT PRIMARY KEY AUTO_INCREMENT,
    appointmentCode VARCHAR(30) UNIQUE NOT NULL,
    visitType VARCHAR(40),
    appointmentState VARCHAR(255),
    scheduledAt TIMESTAMP NULL,
    roomCode VARCHAR(20),
    books INT,
    attends INT,
    coordinates INT,
    FOREIGN KEY (books) REFERENCES Patient(id),
    FOREIGN KEY (attends) REFERENCES Physician(id),
    FOREIGN KEY (coordinates) REFERENCES Nurse(id)
);

CREATE TABLE EncounterNote (
    id INT PRIMARY KEY AUTO_INCREMENT,
    summary TEXT,
    diagnosisCode VARCHAR(20),
    signedAt TIMESTAMP NULL,
    captures INT,
    FOREIGN KEY (captures) REFERENCES Appointment(id)
);

CREATE TABLE Prescription (
    id INT PRIMARY KEY AUTO_INCREMENT,
    medicationName VARCHAR(120) NOT NULL,
    dosage VARCHAR(80),
    active BOOLEAN DEFAULT TRUE,
    issues INT,
    FOREIGN KEY (issues) REFERENCES Appointment(id)
);

CREATE TABLE LabOrder (
    id INT PRIMARY KEY AUTO_INCREMENT,
    testCode VARCHAR(30) NOT NULL,
    labState VARCHAR(255),
    priority VARCHAR(20),
    requests INT,
    FOREIGN KEY (requests) REFERENCES Appointment(id)
);

CREATE TABLE InsurancePolicy (
    id INT PRIMARY KEY AUTO_INCREMENT,
    providerName VARCHAR(100) NOT NULL,
    policyNumber VARCHAR(40) UNIQUE NOT NULL,
    coverageType VARCHAR(40),
    covered_by INT,
    FOREIGN KEY (covered_by) REFERENCES Patient(id)
);

CREATE TABLE Patient_assigned_to_Physician (
    Patient_id INT,
    Physician_id INT,
    PRIMARY KEY (Patient_id, Physician_id),
    FOREIGN KEY (Patient_id) REFERENCES Patient(id),
    FOREIGN KEY (Physician_id) REFERENCES Physician(id)
);

